using System;using System.Collections.Generic;using System.IO;using System.Linq;using System.Threading.Tasks;using UnityEngine;using UnityEngine.AI;using RoadGunner;using RoadGunner.Editor;using Object=UnityEngine.Object;
public static class WastelandPlayChecks {
 static GameSession s;static LevelLayout l;static List<string> lines=new List<string>();static int failures;static Quaternion axis=Quaternion.Euler(0,45,0);static string report="Documentation/RoadGunner/Wasteland-Restore-2026-10-10/PlayChecks.txt";
 static void Check(string name,bool pass,string detail){if(!pass)failures++;lines.Add((pass?"PASS ":"FAIL ")+name+": "+detail);File.WriteAllLines(report,lines);Debug.Log("WASTELAND "+lines.Last());}
 static async Task Wait(float seconds){float until=Time.realtimeSinceStartup+seconds;while(Time.realtimeSinceStartup<until)await Task.Delay(30);}
 static void Isolate(){s.Restart();s.spawns.enabled=false;s.turret.enabled=false;s.health.DamageEnabled=false;foreach(var r in s.spawns.pool)r.Despawn();foreach(var b in s.spawns.buggyPool)b.Despawn();s.input.testInput=true;s.input.testDirection=Vector2.zero;s.input.testBrake=true;s.vehicle.Body.constraints=RigidbodyConstraints.None;}
 static Vector2 Local(Vector3 world){var p=Quaternion.Inverse(axis)*world;return new Vector2(p.x,p.z);}
 static Vector3 W(float x,float z,float y=.7f)=>axis*new Vector3(x*2.5f,y,z*2.5f);
 static async Task Drive(string name,Vector2 from,Vector2[] route,float yaw=0,float timeout=80){Isolate();s.vehicle.ResetPose(W(from.x,from.y),Quaternion.Euler(0,45+yaw,0));s.follow.Snap();await Wait(.5f);s.input.testBrake=false;int step=0;float end=Time.realtimeSinceStartup+timeout;int minWheels=4;float minUp=1,maxSpeed=0;while(step<route.Length&&Time.realtimeSinceStartup<end){Vector2 delta=route[step]*2.5f-Local(s.vehicle.transform.position);if(delta.magnitude<3){step++;continue;}float throttle=Mathf.Lerp(.36f,.65f,Mathf.InverseLerp(3,12,delta.magnitude));s.input.testDirection=delta.normalized*throttle;minWheels=Math.Min(minWheels,s.vehicle.GroundedWheels);minUp=Mathf.Min(minUp,Vector3.Dot(s.vehicle.transform.up,Vector3.up));maxSpeed=Mathf.Max(maxSpeed,s.vehicle.Body.linearVelocity.magnitude);await Task.Delay(30);}s.input.testDirection=Vector2.zero;s.input.testBrake=true;await Wait(.35f);Check("drive "+name,step==route.Length&&minWheels>=3&&minUp>.9f,"waypoints="+step+"/"+route.Length+", end="+Local(s.vehicle.transform.position)+", minimum grounded="+minWheels+", upright="+minUp.ToString("F3")+", maxSpeed="+maxSpeed.ToString("F2"));}
 static async Task HealRate(string name,float scale){s.health.ResetHealth();s.health.Damage(s.health.tuning.vehicleHealth*.8f,false);Time.timeScale=scale;await Wait(.1f);float hp=s.health.Current,t=Time.time;int frame=Time.frameCount;await Wait(1.5f);float actual=s.health.Current-hp,expected=s.health.tuning.vehicleHealth*.1f*(Time.time-t);Check(name,Mathf.Abs(actual-expected)<1.5f,"healed="+actual.ToString("F3")+", expected="+expected.ToString("F3")+", frames="+(Time.frameCount-frame)+", scaledSeconds="+(Time.time-t).ToString("F3"));Time.timeScale=1;}
 public static async Task<string> Main(){if(!UnityEditor.EditorApplication.isPlaying)throw new Exception("Enter Play");l=Object.FindAnyObjectByType<LevelLayout>();s=l.session;Application.runInBackground=true;GameObject overlap=null,child=null;var workshop=Object.FindAnyObjectByType<RepairWorkshop>();
 try{s.Restart();s.turret.enabled=false;s.health.DamageEnabled=false;await Wait(.7f);Check("authored raiders on NavMesh",s.spawns.authoredRaiders.All(r=>r.Alive&&r.agent.isOnNavMesh),"alive="+s.spawns.authoredRaiders.Count(r=>r.Alive)+"/19, cap="+s.spawns.tuning.activeCap);Check("spawn grounded",s.vehicle.GroundedWheels==4&&Vector2.Distance(Local(s.vehicle.transform.position),new Vector2(0,-120))<.4f,"grounded="+s.vehicle.GroundedWheels);
 var nodes=new[]{new Vector2(0,-48),new Vector2(-22,-16),new Vector2(-18,6),new Vector2(12,-12),new Vector2(6,3),new Vector2(0,22),new Vector2(-33,35),new Vector2(-40,24),new Vector2(-12,47),new Vector2(0,58),new Vector2(24,40),new Vector2(38,37),new Vector2(41,58)};foreach(var point in nodes){var path=new NavMeshPath();bool sample=NavMesh.SamplePosition(W(point.x,point.y,0),out var hit,5,NavMesh.AllAreas);bool ok=sample&&NavMesh.CalculatePath(W(0,-48,0),hit.position,NavMesh.AllAreas,path)&&path.status==NavMeshPathStatus.PathComplete;Check("connected navigation "+point,ok,"status="+path.status);}
 Isolate();s.vehicle.Body.constraints=RigidbodyConstraints.FreezeAll;s.vehicle.ResetPose(workshop.transform.position+Vector3.up*.7f,axis);s.health.DamageEnabled=true;await HealRate("automatic repair scaled time 1.0",1);Check("repair feedback active",workshop.IsRepairing&&workshop.activeRepairEffect.activeSelf&&workshop.repairingLabel.gameObject.activeSelf,"effect and HUD");await HealRate("automatic repair scaled time 0.5",.5f);
 child=new GameObject("Temporary multiple colliders check");child.transform.SetParent(s.vehicle.transform,false);child.AddComponent<BoxCollider>().isTrigger=true;child.AddComponent<SphereCollider>().isTrigger=true;overlap=new GameObject("Temporary overlap check");overlap.transform.position=workshop.transform.position;var other=overlap.AddComponent<RepairWorkshop>();other.session=s;other.healingRadius=10;other.maximumHealthFractionPerSecond=.1f;await HealRate("overlap and child colliders do not multiply",1);Object.Destroy(overlap);Object.Destroy(child);await Wait(.1f);
 float pre=s.health.Current;s.health.Damage(5,false);Check("repair grants no invulnerability",Mathf.Abs(s.health.Current-(pre-5))<.01f,"damage taken="+(pre-s.health.Current));
 s.vehicle.ResetPose(workshop.transform.position+axis*new Vector3(10.3f,.7f,0),axis);await Wait(.1f);float outside=s.health.Current;await Wait(.5f);Check("leaving radius stops repair",s.health.Current==outside&&!workshop.IsRepairing&&!workshop.activeRepairEffect.activeSelf&&!workshop.repairingLabel.gameObject.activeSelf,"HP="+outside);
 for(int i=0;i<3;i++){s.vehicle.ResetPose(workshop.transform.position+Vector3.up*.7f,axis);await Wait(.15f);s.vehicle.ResetPose(workshop.transform.position+axis*new Vector3(11,.7f,0),axis);await Wait(.1f);}s.vehicle.ResetPose(workshop.transform.position+Vector3.up*.7f,axis);await HealRate("repeated entry resumes single rate",1);
 s.SetPaused(true);float paused=s.health.Current;await Wait(.5f);Check("pause stops healing and feedback",s.health.Current==paused&&!workshop.IsRepairing&&!workshop.activeRepairEffect.activeSelf,"HP="+paused);s.SetPaused(false);await Wait(.2f);Check("resume resumes healing",s.health.Current>paused&&workshop.IsRepairing,"HP="+s.health.Current);
 s.health.ResetHealth();s.health.Damage(1,false);await Wait(.5f);Check("clamp and stop at max HP",s.health.Current==s.health.tuning.vehicleHealth&&!workshop.IsRepairing&&!workshop.activeRepairEffect.activeSelf&&!workshop.repairingLabel.gameObject.activeSelf,"HP="+s.health.Current);
 s.health.Damage(99999,false);await Wait(.4f);Check("death does not revive",s.health.Current==0&&s.State==SessionState.Defeated&&!workshop.IsRepairing&&!workshop.activeRepairEffect.activeSelf,"HP="+s.health.Current+", state="+s.State);s.Restart();await Wait(.3f);Check("restart clears repair and restores health",s.health.Current==s.health.tuning.vehicleHealth&&!workshop.IsRepairing&&s.Playing,"state="+s.State);
 await Drive("main axis",new Vector2(0,-48),new[]{new Vector2(1,-26),new Vector2(0,0),new Vector2(0,22),new Vector2(-1,42),new Vector2(0,58)},0,130);
 await Drive("southwest camp",new Vector2(0,-9),new[]{new Vector2(-11,-9),new Vector2(-22,-16)},-90,50);
 await Drive("west branch and arena",new Vector2(0,22),new[]{new Vector2(-17,22),new Vector2(-25,27),new Vector2(-28,33),new Vector2(-33,35)},-90,80);
 await Drive("northeast camp",new Vector2(0,36.5f),new[]{new Vector2(14,36.5f),new Vector2(24,40)},90,65);
 await Drive("sealed entrance approach",new Vector2(24,40),new[]{new Vector2(37,38)},90,40);
 await Drive("northeast veteran pocket",new Vector2(26,43),new[]{new Vector2(32,47),new Vector2(33,53),new Vector2(38,57),new Vector2(41,58)},25,90);
 await Drive("service bay entry turn and exit",new Vector2(0,-17),new[]{new Vector2(12,-17),new Vector2(12,-12),new Vector2(12,-7),new Vector2(0,-7)},90,90);
 Isolate();s.vehicle.ResetPose(W(0,62),axis);await Wait(.4f);s.input.testBrake=false;s.input.testDirection=new Vector2(0,.65f);await Wait(5);s.input.testDirection=Vector2.zero;s.input.testBrake=true;Check("north gate blocks car",Local(s.vehicle.transform.position).y<162,"position="+Local(s.vehicle.transform.position));
 Isolate();s.vehicle.ResetPose(W(-44,24),Quaternion.Euler(0,-45,0));await Wait(.4f);s.input.testBrake=false;s.input.testDirection=new Vector2(-.65f,0);await Wait(5);s.input.testDirection=Vector2.zero;s.input.testBrake=true;Check("west gate blocks car",Local(s.vehicle.transform.position).x>-122,"position="+Local(s.vehicle.transform.position));
 Isolate();s.vehicle.Body.constraints=RigidbodyConstraints.FreezeAll;var r=s.spawns.authoredRaiders[0];r.Spawn(s.vehicle.transform.position+axis*new Vector3(0,-.7f,6),-1,0);r.enabled=false;s.turret.enabled=true;int shots=s.turret.ShotsFired;float end=Time.realtimeSinceStartup+6;while(r.Alive&&Time.realtimeSinceStartup<end)await Task.Delay(30);Check("existing turret targets and kills restored raider",!r.Alive&&s.turret.ShotsFired>shots,"shots="+(s.turret.ShotsFired-shots));s.turret.enabled=false;end=Time.realtimeSinceStartup+8;while(s.Scrap<1&&Time.realtimeSinceStartup<end)await Task.Delay(30);Check("loot harpoon and HUD",s.Scrap==1&&s.pickups.ActiveCount==0&&s.hud.scrapText.text=="001","scrap="+s.Scrap+", HUD="+s.hud.scrapText.text);r.enabled=true;
 Isolate();s.vehicle.ResetPose(workshop.transform.position+axis*new Vector3(-6,.7f,0),axis);s.Recover();Check("recovery at clear workshop apron",Vector3.Distance(s.vehicle.transform.position,l.recoveryPoints.First(t=>t!=l.playerSpawn).position)<.1f,"position="+s.vehicle.transform.position);
 }finally{Time.timeScale=1;if(overlap)Object.Destroy(overlap);if(child)Object.Destroy(child);foreach(var r in s.spawns.pool)r.enabled=true;s.vehicle.Body.constraints=RigidbodyConstraints.None;s.spawns.enabled=true;s.turret.enabled=true;s.Restart();}
 return "Failures="+failures+"\n"+string.Join("\n",lines);}
}
